import type { ArticleBlock } from "./articleBlocks";

export type Article = {
  slug: string;
  title: string;
  description: string;
  date: string;
  emoji: string;
  body: string;
  // Нова структурована схема (опціонально).
  // Якщо blocks задані — стаття рендериться через <ArticleBody />.
  // Якщо ні — використовується legacy-рендер з body (markdown-підмножина).
  blocks?: ArticleBlock[];
  subtitle?: string;     // підзаголовок під H1
  category?: string;     // напр. "Фунгіциди · Соняшник · Травень 2026"
  readingTime?: string;  // "7 хв читання"
  // Російські копії — рендеряться на /ru/baza-znan/<slug>.
  // Якщо відсутні — fallback на укр-поля.
  titleRu?: string;
  descriptionRu?: string;
  bodyRu?: string;
  blocksRu?: ArticleBlock[];
  subtitleRu?: string;
  categoryRu?: string;
  readingTimeRu?: string;
};

/** Повертає поля статті для конкретної мови з fallback на укр. */
export function getArticleI18n(article: Article, lang: "uk" | "ru") {
  if (lang === "ru") {
    return {
      title: article.titleRu || article.title,
      description: article.descriptionRu || article.description,
      body: article.bodyRu || article.body,
      blocks: article.blocksRu || article.blocks,
      subtitle: article.subtitleRu || article.subtitle,
      category: article.categoryRu || article.category,
      readingTime: article.readingTimeRu || article.readingTime,
    };
  }
  return {
    title: article.title,
    description: article.description,
    body: article.body,
    blocks: article.blocks,
    subtitle: article.subtitle,
    category: article.category,
    readingTime: article.readingTime,
  };
}

